entries[332460] = { ["name"] = "Auserwählter Tauralus", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Selbst ein ungepanzerter Tauralus ist im Kampf ein wertvoller Verbündeter, denn seine gewaltigen Hörner können sogar eine Plattenrüstung durchbohren.\"\nErfolg:\nMonströse Montage\nKategorie:\nPaktsankten" }
