entries[332462] = { ["name"] = "Gepanzerter kriegsgezüchteter Tauralus", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Den Tauralussen, die den Armeen von Maldraxxus dienen, wurde jegliches Mitgefühl durch Züchtung ausgetrieben. Sie sind nur mit Rüstungen geschmückt, um zu demonstrieren, dass kein Schwert und kein Zauber sie daran hindern kann, ihre Reiter zum Sieg zu tragen.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
