entries[332464] = { ["name"] = "Gepanzerter Seuchenfäulnistauralus", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein voll gepanzerter Tauralus kann unglaubliche Mengen an Schaden einstecken, bevor er zu Boden geht. Das macht ihn in jeder Schlacht zu einem wertvollen Verbündeten.\"\nPakt:\nNekrolords\nVerkäufer:\nSu Zettai\nZone:\nMaldraxxus\nKosten:\n3000" }
entries[332465] = { ["name"] = "Erschaffen" }
entries[332466] = { ["name"] = "Gepanzerter Knochenhuftauralus", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Tauralus ist das bevorzugte Reittier des Hauses der Auserwählten, denn er wird im Kampf noch wütender und bösartiger.\"\nBeute von:\nSabriel die Knochenspalterin\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[332467] = { ["name"] = "Gepanzerter auserwählter Tauralus", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Tauralus hat zwei Schweife, die unentbehrlich sind, um lästiges herumschwirrendes Ungeziefer wie die Blutlaus wegzupeitschen.\"\nErfolg:\nAbhakliste für Tote\nKategorie:\nPaktsankten" }
