entries[332903] = { ["name"] = "Bollwerkkreischer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese gigantischen Fleddermäuse nisten in den Schutzwällen von Schloss Nathria. Sie dienen als Wachen und wurden darauf abgerichtet, Bedrohungen zu neutralisieren, die sich dem Schloss aus der Luft nähern.\"\nErfolg:\nRuhm des Schlachtzüglers von NathriaKategorie:\nDungeons & Schlachtzüge" }
entries[332904] = { ["name"] = "Fledderschwinge des Ernters", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Fledderschwingen der Ernter haben keine Angst vor den Schlundgebundenen und versenken ihre Fangzähne mit Freuden in allem, was Sündensturz bedroht.\"\nBeute von:\nKriegskasse des Ernters\nZone:\nDer Schlund" }
entries[332905] = { ["name"] = "Flieger des Endmorasts", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese fliegenden Verschlinger kamen durch Portale, über die nur wenig bekannt ist. Sie haben ein Zuhause im Endmorast von Revendreth gefunden, wo sie sich von latenter Anima ernähren.\"\nBeute von:\nFamu der Unendliche\nZone:\nRevendreth" }
